"""Server-side validation logic for the registration wizard.

This module is intentionally free of any Reflex imports so it can be
imported and unit-tested with a plain ``python3`` interpreter.
"""

from __future__ import annotations

from typing import Dict


def _is_valid_email(email: str) -> bool:
    """Return True when *email* looks like a valid email address.

    The rules are deliberately simple (no regex dependency required):
      * exactly one ``@`` character
      * non-empty local part (before the ``@``)
      * domain part (after the ``@``) contains at least one ``.``
    """
    if not isinstance(email, str):
        return False
    parts = email.split("@")
    if len(parts) != 2:
        return False
    local, domain = parts
    if not local:
        return False
    if "." not in domain:
        return False
    return True


def validate_step(step: int, data: dict) -> Dict[str, str]:
    """Validate a single wizard step.

    Parameters
    ----------
    step:
        ``1``, ``2`` or ``3`` — the step number to validate.
    data:
        A mapping that may contain the keys ``email``, ``password``,
        ``confirm_password``, ``full_name`` and ``accept_terms``.

    Returns
    -------
    dict
        A mapping of *field name* → *error message* for every invalid
        field.  An empty ``dict`` means the step is valid.
    """
    if data is None:
        data = {}

    errors: Dict[str, str] = {}

    if step == 1:
        email = data.get("email")
        if email is None or not str(email).strip():
            errors["email"] = "Email is required"
        elif not _is_valid_email(str(email).strip()):
            errors["email"] = "Invalid email address"

    elif step == 2:
        password = data.get("password")
        if password is None:
            password = ""
        confirm = data.get("confirm_password")
        if confirm is None:
            confirm = ""

        # Password checks — evaluated strictly in order.
        if len(password) < 8:
            errors["password"] = "Password must be at least 8 characters"
        elif not any(c.isupper() for c in password):
            errors["password"] = "Password must contain an uppercase letter"
        elif not any(c.islower() for c in password):
            errors["password"] = "Password must contain a lowercase letter"
        elif not any(c.isdigit() for c in password):
            errors["password"] = "Password must contain a digit"

        if confirm != password:
            errors["confirm_password"] = "Passwords do not match"

    elif step == 3:
        full_name = data.get("full_name")
        if full_name is None or not str(full_name).strip():
            errors["full_name"] = "Full name is required"

        accept = data.get("accept_terms")
        if not accept:
            errors["accept_terms"] = "You must accept the terms"

    return errors

